/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { APP_CONFIG } from './app-config.service';
import { AppConfig, emptyConfig } from './app-config.model';
import { availableLanguages, defaultLanguage, defaultTenant, DefaultsService } from './defaults.service';

describe('DefaultsService', () => {
  it('reads i18n.default-lang and tenant.default from the configuration', () => {
    const config = signal<AppConfig>({
      ...emptyConfig('test'),
      i18n: { 'default-lang': 'es', 'available-langs': ['es', 'pt'] },
      tenant: { default: 'acme' },
    });
    TestBed.configureTestingModule({ providers: [{ provide: APP_CONFIG, useValue: config }] });
    const defaults = TestBed.inject(DefaultsService);

    expect(defaults.language()).toBe('es');
    expect(defaults.tenant()).toBe('acme');
    expect(defaults.availableLanguages()).toEqual(['es', 'pt']);

    config.set({ ...config(), i18n: { 'default-lang': 'fr' } });
    expect(defaults.language()).toBe('fr');
  });

  it('falls back when the configuration has no defaults', () => {
    expect(defaultLanguage({})).toBe('en');
    expect(defaultTenant({})).toBe('main');
    expect(availableLanguages({})).toEqual(['en']);
  });

  it('always includes the default language among the available ones', () => {
    expect(availableLanguages({ 'default-lang': 'es', 'available-langs': ['pt', 'fr'] })).toEqual(['pt', 'fr', 'es']);
  });
});
